But this would cover the torso; okay.

Arms:
```js
let arm = state==='walk' ? [1,0,-1,0][f] : 0;
const armY = 21;
if(!side){
 // left
 r(g,cx-9,armY-arm,3,10,pal.tunic);
 r(g,cx-9,armY+8-arm,3,3,pal.skin);
 // right
 r(g,cx+6,armY+arm,3,10,pal.tunic);
 r(g,cx+6,armY+8+arm,3,3,pal.skin);
 if(talk){
   // right hand raised
   r(g,cx+7,armY-5,3,7,pal.tunic);
   r(g,cx+7,armY-7,3,3,pal.skin);
 }
 if(act){
   // both hands forward/down
   r(g,cx+7,armY+4,7,3,pal.tunic);
   r(g,cx+13,armY+4,3,3,pal.skin);
 }
 if(atk){
   // sword arm extended
   r(g,cx+7,armY+2,6,3,pal.tunic);
   r(g,cx+12,armY+2,3,3,pal.skin);
 }
} else {
 // visible arm
 const ax = side>0?cx+6:cx-9;
 r(g,ax,armY+arm,3,10,pal.tunic);
 r(g,ax,armY+8+arm,3,3,pal.skin);
 if(talk){
   const hx = cx+side*4;
   r(g,hx-1,armY-3,3,7,pal.tunic);
   r(g,hx-1,armY-5,3,3,pal.skin);
 }
 if(act){
   const ex = side>0?cx+8:cx-14;
   r(g,ex,armY+3,6,3,pal.tunic);
   r(g,side>0?ex+5:ex-3,armY+3,3,3,pal.skin);
 }
 if(atk){
   const ex = side>0?cx+8:cx-12;
   r(g,ex,armY+1,5,3,pal.tunic);
   r(g,side>0?ex+4:ex-3,armY+1,3,3,pal.skin);
 }
}
```
`r` with x maybe float; ensure integers. Use Math.round in r.

Head:
```js
const hx = cx + (side? side*1:0);
const hy = 7;
r(g,hx-6,hy,12,13,pal.outline);
if(!back){
