 r(g,hx-4,hy+2,8,1,pal.gold);
} else {
 // back of head hair
 r(g,hx-6,hy+1,12,12,pal.hair);
 r(g,hx-5,hy+2,10,9,pal.hairLight? maybe)
 r(g,hx-5,hy+2,3,10,pal.hairLight);
 r(g,hx+3,hy+3,2,9,pal.hairDark);
