  cloak: '#6e5b8c', cloakDark: '#3d3053', cloakShade: '#4b3c63', cloakLight: '#9b86b7'
};

/* ── 8-direction character sprite generation ───────────────────────────── */
const DIRS = ['S', 'SE', 'E', 'NE', 'N', 'NW', 'W', 'SW'];
const STATES = { idle: [0, 1], walk: [0, 1, 2, 3], talk: [0, 1], interact: [0, 1], attack: [0, 1], hurt: [0] };

function drawCape(g, pal, dir, state, f, cx) {
  const back = dir === 'N' || dir === 'NE' || dir === 'NW';
  const side = dir.includes('E') ? 1 : dir.includes('W') ? -1 : 0;
  const sway = state === 'walk' ? [0, 1, 0, -1][f] : 0;
  if (back) {
    poly(g, [[cx - 8, 19], [cx + 8, 19], [cx + 10, 33 + sway], [cx + 5, 39], [cx, 36], [cx - 5, 39], [cx - 10, 33 + sway]], pal.cloakDark);
    poly(g, [[cx - 6, 20], [cx + 6, 20], [cx + 7, 33], [cx, 37], [cx - 7, 33]], pal.cloak);
    p(g, cx - 5, 21, 2, 13, pal.cloakLight);
    p(g, cx + 3, 22, 2, 11, pal.cloakShade);
  } else if (side) {
    const bx = cx - side * 6;
    poly(g, [[bx, 21], [bx - side * 5, 24], [bx - side * 4, 35 + sway], [bx + side * 2, 33]], pal.cloakDark);
    poly(g, [[bx, 22], [bx - side * 3, 25], [bx - side * 2, 33], [bx + side * 2, 32]], pal.cloak);
    p(g, cx - 8, 21, 3, 14, pal.cloakDark);
    p(g, cx + 5, 21, 3, 14, pal.cloakDark);
    p(g, cx - 7, 22, 2, 12, pal.cloak);
    p(g, cx + 6, 22, 2, 12, pal.cloak);
  } else {
    poly(g, [[cx - 8, 20], [cx - 3, 20], [cx - 4, 35], [cx - 8, 38]], pal.cloakDark);
    poly(g, [[cx + 3, 20], [cx + 8, 20], [cx + 8, 38], [cx + 4, 35]], pal.cloakDark);
    poly(g, [[cx - 7, 21], [cx - 3, 21], [cx - 4, 33], [cx - 7, 36]], pal.cloak);
    poly(g, [[cx + 3, 21], [cx + 7, 21], [cx + 7, 36], [cx + 4, 33]], pal.cloak);
    p(g, cx - 7, 22, 2, 11, pal.cloakLight);
    p(g, cx + 5, 22, 2, 11, pal.cloakLight);
  }
}

function drawCharFrame(g, dir, state, f, pal, opt = {}) {
  const side = dir.includes('E') ? 1 : dir.includes('W') ? -1 : 0;
  const back = dir === 'N' || dir === 'NE' || dir === 'NW';
  const talk = state === 'talk', act = state === 'interact', atk = state === 'attack', hurt = state === 'hurt';
  const step = state === 'walk' ? [1, 0, -1, 0][f] : 0;
  const bob = state === 'idle' && f === 1 ? 1 : (state === 'walk' && (f === 1 || f === 3) ? 1 : 0);
  const lean = act ? (side || 1) : hurt ? -1 : 0;
  const cx = 16;

  g.save();
  g.translate(lean, -bob);

  drawCape(g, pal, dir, state, f, cx);

  /* legs */
  if (side) {
    const lx = cx - 2 - side * step * 2;
    const rx = cx + 1 + side * step * 2;
    p(g, lx, 33, 4, 9, pal.leatherDark);
    p(g, lx, 40, 5, 5, pal.boots);
    p(g, rx, 33, 4, 10, pal.leather);
    p(g, rx, 40, 5, 5, pal.boots);
    p(g, lx, 39, 5, 1, pal.outline);
    p(g, rx, 39, 5, 1, pal.outline);
  } else {
    const lx = cx - 5 + (step > 0 ? 1 : 0);
    const rx = cx + 1 + (step < 0 ? 1 : 0);
    p(g, lx, 33, 5, 9, pal.leather);
    p(g, lx, 41, 5, 4, pal.boots);
    p(g, rx, 33, 5, 9, pal.leatherDark);
    p(g, rx, 41, 5, 4, pal.boots);
    p(g, lx, 40, 5, 1, pal.outline);
    p(g, rx, 40, 5, 1, pal.outline);
  }

  /* torso */
  p(g, cx - 6, 19, 12, 15, pal.outline);
  p(g, cx - 5, 20, 10, 13, pal.tunic);
  p(g, cx - 5, 20, 10, 2, pal.tunicLight);
  p(g, cx - 5, 29, 10, 2, pal.leather);
  p(g, cx - 1, 29, 3, 2, pal.gold);
  if (!back) {
    p(g, cx - 2, 23, 4, 6, pal.tunicShade);
    p(g, cx - 1, 24, 2, 1, pal.gold);
    p(g, cx - 1, 26, 2, 1, pal.gold);
  }
  if (opt.robe) {
    p(g, cx - 6, 19, 12, 24, pal.robe);
    p(g, cx - 6, 33, 12, 9, pal.robeShade);
    p(g, cx - 7, 41, 14, 2, pal.robeLight);
    p(g, cx - 1, 22, 2, 16, pal.gold);
  }
  if (back) {
    p(g, cx - 5, 20, 10, 13, pal.cloak);
    p(g, cx - 4, 21, 8, 11, pal.cloakShade);
    p(g, cx - 3, 22, 2, 9, pal.cloakLight);
  }

  /* arms */
  const arm = state === 'walk' ? [1, 0, -1, 0][f] : 0;
  const armY = 21;
  if (!side) {
    p(g, cx - 9, armY - arm, 3, 10, pal.tunic);
    p(g, cx - 9, armY + 8 - arm, 3, 3, pal.skin);
    p(g, cx + 6, armY + arm, 3, 10, pal.tunic);
    p(g, cx + 6, armY + 8 + arm, 3, 3, pal.skin);
    if (talk) {
      p(g, cx + 7, armY - 5, 3, 7, pal.tunic);
      p(g, cx + 7, armY - 7, 3, 3, pal.skin);
    }
    if (act) {
      p(g, cx + 7, armY + 4, 7, 3, pal.tunic);
      p(g, cx + 13, armY + 4, 3, 3, pal.skin);
    }
    if (atk) {
      p(g, cx + 7, armY + 2, 6, 3, pal.tunic);
      p(g, cx + 12, armY + 2, 3, 3, pal.skin);
    }
  } else {
    const ax = side > 0 ? cx + 6 : cx - 9;
    p(g, ax, armY + arm, 3, 10, pal.tunic);
    p(g, ax, armY + 8 + arm, 3, 3, pal.skin);
    if (talk) {
      const hx = cx + side * 4;
      p(g, hx - 1, armY - 3, 3, 7, pal.tunic);
      p(g, hx - 1, armY - 5, 3, 3, pal.skin);
    }
    if (act) {
      const ex = side > 0 ? cx + 8 : cx - 14;
      p(g, ex, armY + 3, 6, 3, pal.tunic);
      p(g, side > 0 ? ex + 5 : ex - 3, armY + 3, 3, 3, pal.skin);
    }
    if (atk) {
      const ex = side > 0 ? cx + 8 : cx - 12;
      p(g, ex, armY + 1, 5, 3, pal.tunic);
      p(g, side > 0 ? ex + 4 : ex - 3, armY + 1, 3, 3, pal.skin);
    }
  }

  /* head */
  const hx = cx + (side ? side : 0);
  const hy = 7;
  p(g, hx - 6, hy, 12, 13, pal.outline);
  if (!back) {
    p(g, hx - 5, hy + 2, 10, 10, pal.skin);
    p(g, hx - 4, hy + 9, 8, 2, pal.skinShade);
    p(g, hx - 7, hy - 1, 14, 4, pal.hair);
    p(g, hx - 6, hy, 12, 2, pal.hairLight);
    p(g, hx - 7, hy + 2, 3, 10, pal.hair);
    p(g, hx + 4, hy + 2, 3, 10, pal.hair);
    if (side) {
      const ex = hx + side * 2;
      p(g, ex, hy + 7, 2, 2, pal.eye);
      p(g, ex - 1, hy + 11, 3, 1, talk ? pal.mouth : pal.skinShade);
    } else {
      p(g, hx - 3, hy + 7, 2, 2, pal.eye);
      p(g, hx + 1, hy + 7, 2, 2, pal.eye);
      if (talk) p(g, hx - 1, hy + 11, 3, 1, pal.mouth);
      else p(g, hx - 1, hy + 11, 2, 1, pal.skinShade);
    }
    p(g, hx - 5, hy + 1, 2, 5, pal.hairLight);
    p(g, hx + 4, hy + 3, 1, 7, pal.hairDark);
    p(g, hx - 4, hy + 2, 8, 1, pal.gold);
    if (hurt) {
      p(g, hx - 3, hy + 7, 2, 1, pal.eye);
      p(g, hx + 1, hy + 7, 2, 1, pal.eye);
    }
  } else {
    p(g, hx - 6, hy + 1, 12, 12, pal.hair);
    p(g, hx - 5, hy + 2, 3, 10, pal.hairLight);
    p(g, hx + 3, hy + 3, 2, 9, pal.hairDark);
    p(g, hx - 5, hy + 10, 10, 7, pal.hair);
    p(g, hx - 4, hy + 15, 8, 3, pal.hairDark);
    p(g, hx - 4, hy + 2, 8, 1, pal.gold);
  }
  if (hurt) p(g, hx - 2, hy + 11, 4, 1, pal.mouth);

  /* staff or sword */
  if (opt.staff) {
    p(g, cx + 10, 10, 2, 34, pal.leatherDark);
    p(g, cx + 9, 8, 4, 4, pal.gold);
    p(g, cx + 9, 6, 4, 2, '#dfe8ff');
    p(g, cx + 10, 5, 2, 1, '#ffffff');
  }
  if (opt.weapon) {
    if (atk) {
      const bx = side > 0 ? cx + 10 : cx - 12;
      poly(g, [[bx, 18], [bx + 3, 16], [bx + 12, 8], [bx + 14, 10], [bx + 5, 18]], pal.metal);
      p(g, bx, 19, 5, 2, pal.gold);
    } else {
      poly(g, [[cx + 5, 17], [cx + 8, 19], [cx + 1, 34], [cx - 2, 32]], pal.leatherDark);
      p(g, cx + 5, 17, 4, 2, pal.gold);
      p(g, cx + 1, 30, 3, 4, pal.metalDark);
    }
  }

  /* rim light */
  p(g, cx + (side > 0 ? 8 : 5), 20, 1, 11, pal.rim);
  g.restore();
}

function buildCharacter(pal, opt = {}) {
  const sheet = {};
  for (const dir of DIRS) {
    sheet[dir] = {};
    for (const state in STATES) {
      sheet[dir][state] = STATES[state].map(f => {
        const s = sprite(32, 48);
        drawCharFrame(s.g, dir, state, f, pal, opt);
        return s.c;
      });
    }
  }
  return sheet;
}

function buildHeroSprites() {
  heroSprites = buildCharacter(makePalette(hero.role, hero.color), { weapon: true });
}

/* ── UI ────────────────────────────────────────────────────────────────── */
function overlay(name) {
  overlayNames.forEach(k => $(k).classList.toggle('hidden', k !== name));
  if (name !== 'dialogOverlay' && action.type === 'talk') {
    action.type = 'idle';
    action.t = 0;
    action.target = null;
  }
}
function toast(s) {
  const t = $('toast');
  t.textContent = s;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove('show'), 2300);
}
function updateContinueButton() {
  const b = $('continueGame');
  const has = !!localStorage.getItem('lumina-save');
  b.disabled = !has;
  b.style.opacity = has ? '1' : '.45';
}
function drawAvatar() {
  const c = $('heroAvatar');
  if (!c || !heroSprites) return;
  const g = c.getContext('2d');
  g.imageSmoothingEnabled = false;
  g.clearRect(0, 0, c.width, c.height);
  g.fillStyle = 'rgba(10,20,14,.18)';
  g.beginPath(); g.ellipse(38, 103, 22, 6, 0, 0, 7); g.fill();
  const img = heroSprites.S.idle[Math.floor(clock * 2) % 2];
  g.drawImage(img, 6, 7, 64, 96);
}
function renderRelics() {
  const box = $('relicList');
  if (!box) return;
  box.innerHTML = '';
  if (!relicInventory.length) {
    const e = document.createElement('span');
    e.className = 'empty-relic';
    e.textContent = 'Aún no has encontrado reliquias.';
    box.appendChild(e);
    return;
  }
  relicInventory.forEach(r => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'relic-btn' + (artifact === r && artifactEquipped ? ' on' : '');
    b.innerHTML = `<b>${r.icon}</b> ${esc(r.name)}`;
    b.title = r.desc;
    b.onclick = () => {
      if (artifact === r && artifactEquipped) {
        artifactEquipped = false;
        toast(`${r.name} guardada.`);
      } else {
        artifact = r;
        artifactEquipped = true;
        toast(`${r.name} equipada.`);
      }
      updateUI();
    };
    box.appendChild(b);
  });
}
function updateUI() {
  $('heroName').textContent = hero.name;
  $('heroClass').textContent = `${hero.role} · Nv. ${hero.level}`;
  $('hpText').textContent = `${Math.max(0, hero.hp)} / ${hero.maxHp}`;
  $('hpBar').style.width = `${clamp(100 * hero.hp / hero.maxHp, 0, 100)}%`;
  $('xpText').textContent = `${hero.xp} / ${hero.level * 20}`;
  $('xpBar').style.width = `${clamp(100 * hero.xp / (hero.level * 20), 0, 100)}%`;
  $('goldText').textContent = hero.gold;
  $('powerText').textContent = hero.damage + (artifactEquipped && artifact ? artifact.power : 0);
  $('artifactSlot').textContent = artifact ? artifact.icon : '◇';
  $('miniArtifact').textContent = artifactEquipped && artifact ? artifact.icon : '◇';
  if (artifact) {
    $('artifactCopy').innerHTML = `<strong>${esc(artifact.name)}</strong>${artifactEquipped ? 'Equipado · ' : 'Guardado · '}+${artifact.power} daño`;
    $('miniArtifactText').innerHTML = `<strong>${esc(artifact.name)}</strong>${artifactEquipped ? `+${artifact.power} daño` : 'Sin equipar'}`;
  } else {
    $('artifactCopy').innerHTML = '<strong>Espacio de reliquia</strong>Encuentra un artefacto en las profundidades.';
    $('miniArtifactText').innerHTML = '<strong>Vacío</strong>Explora para encontrar magia.';
  }
  renderRelics();
  drawAvatar();
  updateQuestUI();
  updateDayText();
}
function updateQuestUI() {
  const q = [
    ['El primer susurro', 'Habla con la sabia Maelis junto al roble antiguo.', `○ ${quest ? 1 : 0} / 1 · Maelis`],
    ['Hojas para el invierno', 'Recoge una hoja de luna en el claro y llévasela a Maelis.', `○ ${hero.inventory['🌿'] ? 1 : 0} / 1 · Hoja de luna`],
    ['A las Catacumbas', 'Busca las Catacumbas de Raíz al este del claro.', `○ ${dungeonDone ? 1 : 0} / 1 · Entrada`],
    ['El guardián dormido', 'Derrota al guardián y trae su cristal a Maelis.', `○ ${hero.inventory['🔷'] ? 1 : 0} / 1 · Cristal`],
    ['Leyenda de Lúmina', 'El bosque vuelve a estar en paz. Sigue explorando.', '✦ Encargo completado']
  ][clamp(quest, 0, 4)];
  $('questName').textContent = q[0];
  $('questText').textContent = q[1];
  $('questProgress').textContent = q[2];
  $('journalList').innerHTML = `
    <li class="${quest > 0 ? 'done' : ''}"><b>${quest > 0 ? '✓' : '✧'} ${quest === 0 ? 'Habla con Maelis' : quest === 1 ? 'Lleva la hoja a Maelis' : 'La historia de Maelis'}</b><br>${quest < 2 ? 'El roble antiguo guarda una historia.' : 'Una promesa entretejida con el bosque.'}</li>
    <li class="${dungeonDone ? 'done' : ''}">${dungeonDone ? '✓' : '○'} Encuentra las Catacumbas de Raíz.</li>
    <li class="${hero.inventory['🔷'] ? 'done' : ''}">${hero.inventory['🔷'] ? '✓' : '○'} ${hero.inventory['🔷'] ? 'Reliquia recuperada' : 'Derrota al guardián de la mazmorra.'}</li>
    <li class="${quest >= 4 ? 'done' : ''}">${quest >= 4 ? '✓' : '○'} ${quest >= 4 ? 'La leyenda de Lúmina' : 'Completa la historia con Maelis.'}</li>`;
}
function dayLabel() {
  const p = dayClock % 110;
  return p < 25 ? 'AMANECER' : p < 65 ? 'DÍA' : p < 90 ? 'ATARDECER' : 'NOCHE';
}
function isNight() {
  const p = dayClock % 110;
  return p >= 88;
}
function updateDayText() {
  const d = $('dayText');
  if (d) d.textContent = `DÍA ${day} · ${dayLabel()}`;
}
function showDialog(title, body, key, buttons) {
  dialogKey = key || 'maelis';
  $('dialogTitle').textContent = title;
  $('dialogText').textContent = body;
  $('dialogKicker').textContent = 'ENCUENTRO · LÚMINA';
  const box = $('dialogActions');
  box.innerHTML = '';
  buttons.forEach(([label, fn], i) => {
    const b = document.createElement('button');
    b.className = 'btn ' + (i === 0 ? 'primary' : 'ghost');
    b.textContent = label;
    b.onclick = fn;
    box.appendChild(b);
  });
  overlay('dialogOverlay');
}
function showEnding() {
  const relic = artifact ? `${artifact.icon} ${esc(artifact.name)}` : 'Ninguna';
  $('endingStats').innerHTML = `
    <span>HEROÍNA<b>${esc(hero.name)}</b></span>
    <span>VOCACIÓN<b>${esc(hero.role)} · Nv. ${hero.level}</b></span>
    <span>ORO REUNIDO<b>${hero.gold}</b></span>
    <span>RELIQUIA<b>${relic}</b></span>`;
  overlay('endingOverlay');
  action = { type: 'idle', t: 0, target: null };
  saveGame(true);
}
function recoverSave() {
  try { return JSON.parse(localStorage.getItem('lumina-save')); } catch { return null; }
}
function saveGame(silent) {
  try {
    const saveHero = { ...hero, x: mode === 'dungeon' ? worldReturn.x : hero.x, y: mode === 'dungeon' ? worldReturn.y : hero.y };
    const data = {
      v: 3, hero: saveHero, quest, dungeonDone, chestOpen, chest2Open, shrineDay, day, dayClock,
      bossAlive: boss.alive, bossHp: boss.hp, bossX: boss.x, bossY: boss.y,
      mobs: mobs.map(m => ({ alive: m.alive, hp: m.hp })),
      dungeonMobs: dungeonMobs.map(m => ({ alive: m.alive, hp: m.hp })),
      relicInventory, artifactId: artifact ? artifact.id : null, artifactEquipped
    };
    localStorage.setItem('lumina-save', JSON.stringify(data));
    updateContinueButton();
    if (!silent) toast('Aventura guardada en este dispositivo.');
  } catch { if (!silent) toast('No se pudo guardar la partida.'); }
}
function loadGame() {
  const d = recoverSave();
  if (!d) return false;
  try {
    Object.assign(hero, d.hero || {});
    hero.hp = clamp(Number(hero.hp) || 1, 1, Math.max(1, Number(hero.maxHp) || 20));
    hero.maxHp = Math.max(1, Number(hero.maxHp) || 20);
    hero.level = Math.max(1, Number(hero.level) || 1);
    hero.damage = Math.max(1, Number(hero.damage) || 1);
    hero.gold = Math.max(0, Number(hero.gold) || 0);
    hero.speed = Number(hero.speed) || (CLASSES[hero.role] ? CLASSES[hero.role].speed : 38);
    hero.facing = DIRS.includes(hero.facing) ? hero.facing : 'S';
    hero.attack = 0; hero.atkCd = 0;
    if (!hero.inventory) hero.inventory = { '🍎': 0, '🧪': 0, '🪙': hero.gold, '🌿': 0, '🔷': 0 };
    quest = d.quest || 0;
    dungeonDone = !!d.dungeonDone;
    chestOpen = !!d.chestOpen;
    chest2Open = !!d.chest2Open;
    shrineDay = d.shrineDay || 0;
    day = d.day || 1;
    dayClock = d.dayClock || 0;
    relicInventory = Array.isArray(d.relicInventory) ? d.relicInventory : (d.artifact ? [d.artifact] : []);
    artifact = d.artifactId ? relicInventory.find(r => r.id === d.artifactId) : (d.artifact || null);
    if (artifact && !relicInventory.includes(artifact)) relicInventory.push(artifact);
    artifactEquipped = !!d.artifactEquipped && !!artifact;
    boss.alive = d.bossAlive !== false;
    boss.hp = d.bossHp ?? boss.max;
    boss.x = d.bossX || 120;
    boss.y = d.bossY || 51;
    if (d.mobs) d.mobs.forEach((v, i) => { if (mobs[i]) Object.assign(mobs[i], v); });
    if (d.dungeonMobs) d.dungeonMobs.forEach((v, i) => { if (dungeonMobs[i]) Object.assign(dungeonMobs[i], v); });
    buildHeroSprites();
    started = true;
    mode = 'world';
    action = { type: 'idle', t: 0, target: null };
    moving = false;
    bossCd = 0;
    cam.x = clamp(hero.x - SW / 2, 0, W * T - SW);
    cam.y = clamp(hero.y - SH / 2, 0, H * T - SH);
    updateUI();
    overlay(null);
    toast(`¡Bienvenida de vuelta, ${hero.name}!`);
    return true;
  } catch { return false; }
}
function resetGame() {
  hero.name = $('nameInput').value.trim() || 'Lunaria';
  hero.role = document.querySelector('#classChoices .selected').dataset.class;
  hero.color = document.querySelector('#colorChoices .selected').dataset.color;
  const st = CLASSES[hero.role] || CLASSES.Guardiana;
  hero.hp = st.hp; hero.maxHp = st.hp; hero.damage = st.damage; hero.speed = st.speed; hero.gold = st.gold;
  hero.x = 13 * T; hero.y = 15 * T; hero.facing = 'S';
  hero.xp = 0; hero.level = 1; hero.attack = 0; hero.atkCd = 0;
  hero.inventory = { '🍎': 3, '🧪': 1, '🪙': st.gold, '🌿': 0, '🔷': 0 };
  quest = 0; dungeonDone = false; chestOpen = false; chest2Open = false; shrineDay = 0;
  artifact = null; artifactEquipped = false; relicInventory = [];
  day = 1; dayClock = 0; bossCd = 0; shake = 0; flash = 0;
  boss.alive = true; boss.hp = boss.max; boss.x = 120; boss.y = 51;
  mobs.forEach(m => { m.alive = true; m.hp = m.max; });
  dungeonMobs.forEach(m => { m.alive = true; m.hp = m.max; });
  buildHeroSprites();
  started = true; mode = 'world';
  action = { type: 'idle', t: 0, target: null };
  moving = false; walkPhase = 0;
  cam.x = clamp(hero.x - SW / 2, 0, W * T - SW);
  cam.y = clamp(hero.y - SH / 2, 0, H * T - SH);
  updateUI();
  overlay(null);
  toast(`¡Comienza tu aventura, ${hero.name}!`);
}
function openInventory() {
  if (!started) return;
  const grid = $('itemsGrid');
  grid.innerHTML = '';
  for (const [icon, name, description, type] of items) {
    const count = type === 'misc' ? hero.gold : (hero.inventory[icon] || 0);
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'item-slot' + (selected === icon ? ' selected' : '');
    b.textContent = icon;
    const small = document.createElement('small');
    small.textContent = count;
    b.appendChild(small);
    b.title = name;
    b.onclick = () => selectItem(icon);
    grid.appendChild(b);
  }
  renderRelics();
  selectItem(selected);
  overlay('inventoryOverlay');
}
function selectItem(icon) {
  selected = icon;
  const entry = items.find(i => i[0] === icon);
  if (!entry) return;
  const [emoji, name, description, type] = entry;
