/* ── world rules ───────────────────────────────────────────────────────── */
const DIRV = { S: [0, 1], SE: [0.7, 0.7], E: [1, 0], NE: [0.7, -0.7], N: [0, -1], NW: [-0.7, -0.7], W: [-1, 0], SW: [-0.7, 0.7] };

function pathTile(x, y) {
  return (x >= 10 && x <= 14 && y >= 10 && y <= 28) ||
    (y >= 26 && y <= 31 && x >= 11 && x <= 49) ||
    (Math.abs(x - (13 + (y - 12) * 0.75)) < 1.6 && y > 11 && y < 28) ||
    (y >= 29 && y <= 31 && x >= 47 && x <= 82) ||
    (x >= 79 && x <= 81 && y >= 16 && y <= 30) ||
    (y >= 21 && y <= 23 && x >= 68 && x <= 80);
}
function treeTile(x, y) {
  if (x < 1 || y < 1 || x >= W - 1 || y >= H - 1) return false;
  if (pathTile(x, y)) return false;
  if (x >= 51 && x <= 55 && y >= 17 && y <= 28) return false;
  if (Math.hypot(x - 12, y - 12) < 4 || Math.hypot(x - 17, y - 22) < 2.5 || Math.hypot(x - 48, y - 31) < 3) return false;
  if (Math.hypot(x - 82, y - 14) < 3 || Math.hypot(x - 74, y - 22) < 3.5) return false;
  return rand(x, y) > 0.975;
}
function blocked(x, y) {
  if (mode === 'dungeon') return x < 13 || x > SW - 13 || y < 20 || y > SH - 13;
  if (x < 5 || y < 5 || x > W * T - 5 || y > H * T - 5) return true;
  const tx = Math.floor(x / T), ty = Math.floor((y + 3) / T);
  if (treeTile(tx, ty)) return true;
  if (tx >= 51 && tx <= 55 && ty >= 17 && ty <= 28 && !pathTile(tx, ty)) return true;
  if (Math.hypot(x - shrine.x, y - shrine.y) < 7) return true;
  return false;
}
function dir8(dx, dy) {
  if (!dx && !dy) return hero.facing;
  const a = Math.atan2(dy, dx);
  const i = Math.round(a / (Math.PI / 4));
  return ['E', 'SE', 'S', 'SW', 'W', 'NW', 'N', 'NE'][(i + 8) % 8];
}
function nearby() {
  let candidates;
  if (mode === 'dungeon') {
    candidates = [
      ...dungeonMobs.filter(m => m.alive).map(m => ({ ...m, ref: m, kind: 'mob' })),
      ...(boss.alive ? [{ ...boss, ref: boss, kind: 'boss' }] : [])
    ];
  } else {
    candidates = [
      { ...npc, kind: 'npc' },
      { ...chest, kind: 'chest' },
      { ...chest2, kind: 'chest2' },
      { ...shrine, kind: 'shrine' },
      { ...gate, kind: 'gate' },
      ...mobs.filter(m => m.alive).map(m => ({ ...m, ref: m, kind: 'mob' }))
    ];
  }
  return candidates
    .map(o => ({ ...o, d: Math.hypot(hero.x - o.x, hero.y - o.y) }))
    .filter(o => o.d < (o.kind === 'boss' ? 24 : 17))
    .sort((a, b) => a.d - b.d)[0];
}
function setAction(type, seconds, target) {
  action.type = type;
  action.t = seconds;
  action.target = target || null;
  if (target) hero.facing = dir8(target.x - hero.x, target.y - hero.y);
}
function updateAction(dt) {
  if (action.t > 0) {
    action.t -= dt;
    if (action.t <= 0 && action.type !== 'talk') {
      action.type = 'idle';
      action.target = null;
    }
  }
}
function addRelic(r) {
  if (!relicInventory.some(x => x.id === r.id)) relicInventory.push(r);
  if (!artifact || !artifactEquipped) {
    artifact = r;
    artifactEquipped = true;
  }
}
function addFloater(x, y, text, color) {
  floaters.push({ x, y, text, color, life: 1, max: 1 });
}
function spawnBurst(x, y, color, n) {
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2;
    const s = 8 + Math.random() * 24;
    particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s - 20, life: 0.5 + Math.random() * 0.45, max: 1, color });
  }
}
function updateParticles(dt) {
  for (const part of particles) {
    part.x += part.vx * dt;
    part.y += part.vy * dt;
    part.vy += 40 * dt;
    part.life -= dt;
  }
  particles = particles.filter(part => part.life > 0);
}
function updateFloaters(dt) {
  for (const f of floaters) {
    f.y -= 18 * dt;
    f.life -= dt;
  }
  floaters = floaters.filter(f => f.life > 0);
}
function questTarget() {
  if (mode === 'dungeon') return boss.alive ? { x: boss.x, y: boss.y, label: 'Guardián' } : { x: 120, y: 146, label: 'Salida' };
  if (quest === 0) return { x: npc.x, y: npc.y, label: 'Maelis' };
  if (quest === 1) return chestOpen ? { x: npc.x, y: npc.y, label: 'Maelis' } : { x: chest.x, y: chest.y, label: 'Hoja de luna' };
  if (quest === 2) return { x: gate.x, y: gate.y, label: 'Catacumbas' };
  if (quest === 3) return hero.inventory['🔷'] ? { x: npc.x, y: npc.y, label: 'Maelis' } : { x: gate.x, y: gate.y, label: 'Catacumbas' };
  return null;
}

/* ── interaction ───────────────────────────────────────────────────────── */
function interact() {
  if (!started) return;
  if (overlayNames.some(k => !$(k).classList.contains('hidden'))) return;
  const t = nearby();
  if (!t) {
    toast('No hay nadie cerca. Explora el claro.');
    return;
  }
  hero.facing = dir8(t.x - hero.x, t.y - hero.y);
  if (t.kind === 'npc') {
    setAction('talk', 9999, npc);
    if (quest === 0) {
      showDialog('Maelis, la sabia', 'Viajera, el bosque te reconoce. Busca una hoja de luna en el claro al este; su luz abrirá un viejo camino. ¿Me ayudarás?', 'maelis', [
        ['Lo haré', () => { quest = 1; updateUI(); overlay(null); toast('Nueva misión: Hojas para el invierno'); }],
        ['Más tarde', () => overlay(null)]
      ]);
    } else if (quest === 1) {
      if (hero.inventory['🌿']) {
        showDialog('Maelis, la sabia', '¡La hoja brilla como en los viejos cantares! Las Catacumbas de Raíz han despertado. Busca su puerta al este. Toma esta bendición.', 'maelis', [
          ['Aceptar bendición', () => { hero.maxHp += 4; hero.hp = hero.maxHp; quest = 2; updateUI(); overlay(null); toast('Bendición de Maelis · +4 vida máxima'); }]
        ]);
      } else {
        showDialog('Maelis, la sabia', 'La hoja de luna crece entre los robles del claro. Un destello plateado te indicará el camino.', 'maelis', [['Entendido', () => overlay(null)]]);
      }
    } else if (quest < 4) {
      if (hero.inventory['🔷']) {
        showDialog('Maelis, la sabia', '¡El cristal ha regresado! Quédate con el artefacto del guardián; el bosque te lo concede. El bosque vuelve a estar en paz.', 'maelis', [
          ['Completar misión', () => { quest = 4; updateUI(); showEnding(); }]
        ]);
      } else {
        showDialog('Maelis, la sabia', 'La puerta antigua está al este, más allá del río. El guardián protege un cristal olvidado.', 'maelis', [['Seguir camino', () => overlay(null)]]);
      }
    } else {
      showDialog('Maelis, la sabia', 'El mundo es grande, caminante. Cada sendero es una historia nueva. Que las estrellas cuiden tu viaje.', 'maelis', [['Gracias', () => overlay(null)]]);
    }
  } else if (t.kind === 'chest' || t.kind === 'chest2') {
    const isSecond = t.kind === 'chest2';
    const opened = isSecond ? chest2Open : chestOpen;
    if (opened) {
      toast('El cofre está vacío.');
      return;
    }
    setAction('interact', 0.8, isSecond ? chest2 : chest);
    if (isSecond) {
      chest2Open = true;
      addRelic(MOTH_RELIC);
      updateUI();
      spawnBurst(chest2.x, chest2.y - 6, '#cde3ff', 22);
      toast('¡Ala de Polilla! +1 daño y +8 velocidad. Equípala en la mochila.');
    } else {
      chestOpen = true;
      hero.gold += 18;
      hero.inventory['🌿']++;
      quest = Math.max(quest, 1);
      updateUI();
      spawnBurst(chest.x, chest.y - 6, '#ffe29a', 18);
      toast('¡Hoja de luna y 18 monedas!');
    }
  } else if (t.kind === 'shrine') {
    setAction('pray', 1.3, shrine);
    if (shrineDay !== day) {
      shrineDay = day;
      hero.hp = hero.maxHp;
      updateUI();
      spawnBurst(shrine.x, shrine.y - 8, '#d9e9b0', 26);
      toast('El altar de la luna restaura tu vitalidad.');
    } else {
      toast('El altar ya te bendijo hoy.');
    }
  } else if (t.kind === 'gate') {
    setAction('interact', 0.8, gate);
    $('dungeonText').textContent = 'La puerta cubierta de raíces cede ante tu presencia. Un guardián duerme en el corazón de la piedra. ¿Descenderás?';
    overlay('dungeonOverlay');
  } else {
    attack(t);
  }
}

/* ── combat ────────────────────────────────────────────────────────────── */
function attack(target) {
  if (!started || hero.atkCd > 0) return;
  hero.atkCd = 0.34;
  const t = target || nearby();
  if (t && (t.kind === 'mob' || t.kind === 'boss')) {
    hero.facing = dir8(t.x - hero.x, t.y - hero.y);
    setAction('attack', 0.24, t);
    hitTarget(t.ref || t);
  } else {
    hero.attack = 0.18;
    setAction('attack', 0.18, null);
    const v = DIRV[hero.facing] || DIRV.S;
    spawnBurst(hero.x + v[0] * 8, hero.y - 4 + v[1] * 8, '#d8c58a', 5);
  }
}
function hitTarget(t) {
  if (!t || !t.alive) return;
  const dmg = hero.damage + (artifactEquipped && artifact ? artifact.power : 0);
  t.hp -= dmg;
  hero.attack = 0.24;
  addFloater(t.x, t.y - 18, `-${dmg}`, '#ffe39a');
  spawnBurst(t.x, t.y - 6, '#ffd27a', 10);
  shake = Math.max(shake, 2);
  if (t.hp <= 0) {
    t.alive = false;
    if (t === boss) {
      hero.xp += 35;
      hero.gold += 40;
      hero.inventory['🔷'] = 1;
      dungeonDone = true;
      quest = 3;
      addRelic(ROOT_RELIC);
      spawnBurst(boss.x, boss.y - 12, '#ffe6a8', 60);
      toast('¡Jefe vencido! Reliquia Corazón de Raíz · +2 daño');
      saveGame(true);
    } else {
      hero.xp += 6;
      hero.gold += 3;
      spawnBurst(t.x, t.y - 6, '#b6e3a1', 16);
      toast('¡Monstruo vencido! +3 oro · experiencia');
    }
    while (hero.xp >= hero.level * 20) {
      hero.xp -= hero.level * 20;
      hero.level++;
      hero.maxHp += 3;
      hero.hp = hero.maxHp;
      hero.damage++;
      addFloater(hero.x, hero.y - 26, `¡NIVEL ${hero.level}!`, '#ffe9a8');
      toast(`¡Nivel ${hero.level}! Tu poder crece.`);
    }
  }
  updateUI();
}
function damagePlayer(n) {
  hero.hp = Math.max(0, hero.hp - n);
  addFloater(hero.x, hero.y - 22, `-${n}`, '#ff9a8a');
  flash = Math.max(flash, 0.18);
  shake = Math.max(shake, 3);
  setAction('hurt', 0.28, null);
  updateUI();
  if (!hero.hp) respawn();
}
function respawn() {
  hero.hp = hero.maxHp;
  hero.x = mode === 'world' ? 13 * T : 120;
  hero.y = mode === 'world' ? 15 * T : 126;
  hero.gold = Math.max(0, hero.gold - 5);
  hero.attack = 0; hero.atkCd = 0; bossCd = 1;
  action = { type: 'idle', t: 0, target: null };
  if (mode === 'world') {
    cam.x = clamp(hero.x - SW / 2, 0, W * T - SW);
    cam.y = clamp(hero.y - SH / 2, 0, H * T - SH);
  }
  updateUI();
  toast('Te han rescatado en el último instante. −5 oro.');
}

/* ── enemies ───────────────────────────────────────────────────────────── */
function updateEnemies(dt) {
  const pack = mode === 'dungeon' ? dungeonMobs : mobs;
  for (const m of pack) {
    if (!m.alive) continue;
    const d = Math.hypot(hero.x - m.x, hero.y - m.y);
    if (d < 44 && d > 9) {
      const nx = m.x + (hero.x - m.x) / d * 14 * dt;
      const ny = m.y + (hero.y - m.y) / d * 14 * dt;
      if (!blocked(nx, m.y)) m.x = nx;
      if (!blocked(m.x, ny)) m.y = ny;
    }
    m.touchCd = Math.max(0, (m.touchCd || 0) - dt);
    if (d < 10 && m.touchCd <= 0) {
      damagePlayer(1);
      m.touchCd = 1.2;
    }
  }
}
function updateBoss(dt) {
  if (mode !== 'dungeon' || !boss.alive) return;
  bossCd = Math.max(0, bossCd - dt);
  const d = Math.hypot(hero.x - boss.x, hero.y - boss.y);
  if (d < 120 && d > 22) {
    boss.x += (hero.x - boss.x) / d * 11 * dt;
    boss.y += (hero.y - boss.y) / d * 11 * dt;
    boss.x = clamp(boss.x, 28, SW - 28);
    boss.y = clamp(boss.y, 38, SH - 24);
  }
  if (d < 24 && bossCd <= 0) {
    damagePlayer(3);
    bossCd = 1.5;
  }
}

/* ── mode / camera / day ───────────────────────────────────────────────── */
function changeMode(next) {
  mode = next;
  if (next === 'dungeon') {
    worldReturn = { x: hero.x, y: hero.y };
    hero.x = 120; hero.y = 126; hero.facing = 'N';
    dungeonMobs.forEach(m => { m.alive = true; m.hp = m.max; m.touchCd = 0; });
    boss.hp = boss.max; boss.x = 120; boss.y = 51; bossCd = 0;
    cam = { x: 0, y: 0 };
    overlay(null);
    $('regionTitle').textContent = '♜ CATACUMBAS DE RAÍZ';
    $('locationText').textContent = 'Catacumbas de Raíz';
    toast('Has descendido a la mazmorra. ¡Cuidado con el guardián!');
  } else {
    hero.x = worldReturn.x; hero.y = worldReturn.y; hero.facing = 'S';
    cam.x = clamp(hero.x - SW / 2, 0, W * T - SW);
    cam.y = clamp(hero.y - SH / 2, 0, H * T - SH);
    overlay(null);
    $('regionTitle').textContent = '✧ PRADO DE LUNARIA';
    $('locationText').textContent = 'Prado de Lunaria';
    toast('Has regresado al bosque.');
  }
  action = { type: 'idle', t: 0, target: null };
  moving = false;
}
function updateCamera(dt) {
  if (mode === 'world') {
    const lookX = hero.facing.includes('E') ? 10 : hero.facing.includes('W') ? -10 : 0;
    const lookY = hero.facing.includes('S') ? 7 : hero.facing.includes('N') ? -7 : 0;
    const tx = clamp(hero.x - SW / 2 + lookX, 0, W * T - SW);
    const ty = clamp(hero.y - SH / 2 + lookY, 0, H * T - SH);
    const k = 1 - Math.pow(0.0018, dt);
    cam.x = lerp(cam.x, tx, k);
    cam.y = lerp(cam.y, ty, k);
  } else {
    cam.x = 0; cam.y = 0;
  }
}
function updateDay(dt) {
  dayClock += dt;
  if (dayClock >= 110) {
    dayClock -= 110;
    day++;
    toast(`Día ${day}. El bosque despierta de nuevo.`);
  }
  updateDayText();
}

/* ── rendering helpers ─────────────────────────────────────────────────── */
const fx = sprite(canvas.width, canvas.height);
const dof = sprite(canvas.width, canvas.height);

function text(s, x, y, color = '#fff', size = 5) {
  ctx.font = `${size}px monospace`;
  ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = color;
  ctx.fillText(s, Math.round(x), Math.round(y));
}
function shadow(x, y, w, h, a = 0.3) {
  ctx.save();
  ctx.globalAlpha = a;
  ctx.fillStyle = '#06100b';
  ctx.beginPath();
  ctx.ellipse(x, y, w, h, 0, 0, 7);
  ctx.fill();
  ctx.restore();
}
function glow(x, y, r, color, a) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, rgba(color, a));
  g.addColorStop(0.45, rgba(color, a * 0.45));
  g.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}
function rr(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}
function speechBubble(x, y) {
  ctx.save();
  ctx.globalAlpha = 0.96;
  ctx.fillStyle = '#f7efd7';
  ctx.strokeStyle = '#65563a';
  ctx.lineWidth = 0.8;
  rr(x - 11, y - 15, 22, 11, 3);
  ctx.fill(); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x - 3, y - 4); ctx.lineTo(x, y); ctx.lineTo(x + 3, y - 4); ctx.closePath();
  ctx.fillStyle = '#f7efd7'; ctx.fill(); ctx.stroke();
  const n = Math.floor(clock * 4) % 4;
  ctx.fillStyle = '#5c5138';
  for (let i = 0; i < 3; i++) {
    ctx.globalAlpha = i < n ? 1 : 0.25;
    ctx.beginPath(); ctx.arc(x - 5 + i * 5, y - 9, 1.1, 0, 7); ctx.fill();
  }
  ctx.restore();
}
function isWater(x, y) { return x >= 51 && x <= 55 && y >= 17 && y <= 28; }

/* ── world entities ────────────────────────────────────────────────────── */
function drawTree(x, y, biome, variant) {
  const set = TREES[biome] || TREES.green;
  const img = set[variant % set.length];
  shadow(x + 4, y + 9, 8, 2.4, 0.32);
  const sway = Math.sin(clock * 1.15 + x * 0.19) * 0.55;
  ctx.drawImage(img, Math.round(x - 8 + sway), Math.round(y - 14), 16, 23);
}
function drawDeco(kind, variant, x, y) {
  const set = DECOS[kind] || DECOS.tuft;
  ctx.drawImage(set[variant % set.length], x, y, 4, 4);
}
function drawChest(x, y, open) {
  shadow(x, y + 5, 8, 2.4, 0.32);
  if (!open) {
    glow(x, y - 2, 12, '#ffd67a', 0.16 + Math.sin(clock * 3 + x) * 0.04);
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(255,229,150,.8)';
    const tw = Math.sin(clock * 2.5 + x) * 2;
    ctx.fillRect(x + 5 + tw, y - 8, 1, 1);
    ctx.fillRect(x - 6 - tw, y - 2, 1, 1);
    ctx.restore();
  }
  ctx.drawImage(open ? CHEST_SPRITES.open : CHEST_SPRITES.closed, Math.round(x - 8), Math.round(y - 10), 16, 14);
}
function drawGate(x, y) {
  shadow(x, y + 6, 14, 3.5, 0.38);
  glow(x, y - 5, 30, '#7fbfa4', 0.12 + Math.sin(clock * 1.7) * 0.04);
  ctx.drawImage(GATE_SPRITE, Math.round(x - 14), Math.round(y - 24), 28, 32);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = 0.35 + Math.sin(clock * 2.2) * 0.12;
  ctx.fillStyle = '#a8ead0';
  ctx.fillRect(x - 5, y - 12, 1, 1); ctx.fillRect(x + 4, y - 7, 1, 1);
  ctx.restore();
}
function drawShrine(x, y) {
  shadow(x, y + 4, 12, 3, 0.35);
  const used = shrineDay === day;
  glow(x, y - 10, used ? 14 : 30, used ? '#83917d' : '#dbeaa8', used ? 0.12 : 0.22 + Math.sin(clock * 1.6) * 0.05);
  ctx.drawImage(SHRINE_SPRITE, Math.round(x - 12), Math.round(y - 20), 24, 24);
  if (!used) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 4; i++) {
      const a = clock * 0.8 + i * 1.7;
      const px = x + Math.cos(a) * (10 + i * 2);
      const py = y - 14 + Math.sin(a * 1.3) * 5;
      ctx.globalAlpha = 0.35 + Math.sin(clock * 2 + i) * 0.2;
      ctx.fillStyle = '#e9f3bd';
      ctx.fillRect(px, py, 1, 1);
    }
    ctx.restore();
  }
}
function drawNPC(x, y) {
  if (started) npc.facing = dir8(hero.x - x, hero.y - y);
  const talking = !$('dialogOverlay').classList.contains('hidden') && dialogKey === 'maelis';
  const state = talking ? 'talk' : 'idle';
  const frames = npcSprites[npc.facing][state];
  const idx = Math.floor(clock * (talking ? 5 : 2)) % frames.length;
  shadow(x, y + 4, 7, 2.2, 0.32);
  ctx.drawImage(frames[idx], Math.round(x - 8), Math.round(y - 20), 16, 24);
  if (talking) speechBubble(x, y - 24);
  else if (Math.hypot(hero.x - x, hero.y - y) < 20 && started && quest === 0) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    glow(x, y - 30, 9, '#ffe9a0', 0.28);
    text('!', x - 1, y - 27, '#fff0a8', 7);
    ctx.restore();
  }
}
function drawHero() {
  let state = 'idle';
  let idx = Math.floor(clock * 2) % 2;
  if (hero.attack > 0) {
    state = 'attack'; idx = Math.floor(clock * 14) % 2;
  } else if (action.type === 'hurt' && action.t > 0) {
    state = 'hurt'; idx = 0;
  } else if (action.type === 'talk') {
    state = 'talk'; idx = Math.floor(clock * 5) % 2;
  } else if (action.type === 'interact' || action.type === 'pray') {
    state = 'interact'; idx = Math.floor(clock * 6) % 2;
  } else if (moving) {
    state = 'walk'; idx = Math.floor(walkPhase) % 4;
  }
  const frames = heroSprites[hero.facing][state] || heroSprites.S.idle;
  const img = frames[idx % frames.length];
  shadow(hero.x, hero.y + 4, 7, 2.2, 0.34);
  if (action.type === 'pray') {
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    glow(hero.x, hero.y - 8, 18, '#e7f0b2', 0.16);
    ctx.restore();
  }
  ctx.drawImage(img, Math.round(hero.x) - 8, Math.round(hero.y) - 20, 16, 24);
  if (hero.attack > 0) drawSlash();
}
function drawSlash() {
  const v = DIRV[hero.facing] || DIRV.S;
  const a = Math.atan2(v[1], v[0]);
  ctx.save();
  ctx.translate(hero.x + v[0] * 3, hero.y - 5 + v[1] * 3);
  ctx.rotate(a);
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineCap = 'round';
  ctx.strokeStyle = 'rgba(255,244,190,.9)';
  ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.arc(7, 0, 8, -1.25, 1.25); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,215,120,.35)';
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.arc(7, 0, 8, -1.1, 1.1); ctx.stroke();
  ctx.restore();
}
function drawMob(m) {
  const frames = MOB_SPRITES[m.type] || MOB_SPRITES.slime;
  const idx = Math.floor(clock * (m.type === 'moth' ? 8 : 5) + m.x * 0.17) % frames.length;
  const img = frames[(idx + frames.length) % frames.length];
  const w = m.type === 'slime' ? 16 : 18;
  const h = m.type === 'slime' ? 12 : 14;
  shadow(m.x, m.y + 5, w * 0.42, 2, 0.3);
  ctx.drawImage(img, Math.round(m.x - w / 2), Math.round(m.y - h + 6), w, h);
  if (m.hp < m.max) {
    ctx.fillStyle = '#2c241f';
    ctx.fillRect(m.x - 5, m.y - h + 1, 10, 1);
    ctx.fillStyle = '#e27f6f';
    ctx.fillRect(m.x - 5, m.y - h + 1, Math.max(1, 10 * m.hp / m.max), 1);
  }
  if (m.type === 'wolf') {
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(255,184,95,.35)';
    ctx.fillRect(m.x + 3, m.y - 3, 1, 1);
    ctx.restore();
  }
}
function drawBoss() {
  const d = Math.hypot(hero.x - boss.x, hero.y - boss.y);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const pulse = 0.16 + Math.sin(clock * 2.2) * 0.04 + (boss.hp < boss.max ? 0.08 : 0);
  glow(boss.x, boss.y - 10, 44, '#b06078', pulse);
  if (d < 110) glow(boss.x, boss.y - 10, 22, '#ffc46b', 0.12);
  ctx.restore();
  const img = BOSS_SPRITES[Math.floor(clock * 2) % 2];
  shadow(boss.x, boss.y + 13, 16, 3.5, 0.38);
  ctx.drawImage(img, Math.round(boss.x - 18), Math.round(boss.y - 24), 36, 36);
  // health bar
  ctx.fillStyle = '#271c24';
  ctx.fillRect(boss.x - 18, boss.y - 33, 36, 3);
  ctx.fillStyle = '#e76564';
  ctx.fillRect(boss.x - 18, boss.y - 33, Math.max(1, 36 * boss.hp / boss.max), 3);
  text('GUARDIÁN', boss.x - 12, boss.y - 37, '#ffe4b2', 5);
}
function drawFloaters() {
  ctx.save();
  for (const f of floaters) {
    ctx.globalAlpha = clamp(f.life * 2, 0, 1);
    text(f.text, f.x - 4, f.y, f.color, 6);
  }
  ctx.restore();
}
function drawParticles() {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const part of particles) {
    ctx.globalAlpha = clamp(part.life / part.max, 0, 1);
    ctx.fillStyle = part.color;
    ctx.fillRect(part.x, part.y, 1, 1);
  }
  ctx.restore();
}

/* ── world render ──────────────────────────────────────────────────────── */
function drawWorld() {
  const tx = Math.floor(hero.x / T), ty = Math.floor(hero.y / T);
  const region = ty > 54 ? 'Bosque de Ámbar' : tx > 60 ? 'Linde Salvaje' : 'Prado de Lunaria';
  $('locationText').textContent = region;
  $('regionTitle').textContent = `✧ ${region.toUpperCase()}`;
  const n = nearby();
  $('interactionHint').style.display = started && n ? 'block' : 'none';
  if (n) {
    $('interactionHint').textContent = n.kind === 'npc' ? 'E · hablar con Maelis'
      : n.kind === 'chest' || n.kind === 'chest2' ? 'E · abrir cofre'
      : n.kind === 'gate' ? 'E · entrar a la mazmorra'
      : n.kind === 'shrine' ? 'E · orar en el altar'
      : 'E / ESPACIO · atacar';
  }

  const sx = shake ? (Math.random() - 0.5) * shake : 0;
  const sy = shake ? (Math.random() - 0.5) * shake : 0;
  const camX = Math.round(cam.x + sx), camY = Math.round(cam.y + sy);
  ctx.save();
  ctx.translate(-camX, -camY);

  const x0 = Math.floor(camX / T) - 1, y0 = Math.floor(camY / T) - 1;
  const cols = Math.ceil(SW / T) + 3, rows = Math.ceil(SH / T) + 3;

  // ground
  for (let y = y0; y < y0 + rows; y++) {
    for (let x = x0; x < x0 + cols; x++) {
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      const biome = y > 53 ? 'moss' : x > 62 ? 'autumn' : 'grass';
      const path = pathTile(x, y);
      const water = isWater(x, y);
      const set = path ? TILES.path : water ? TILES.water : TILES[biome];
      const variant = Math.floor(rand(x * 3 + 7, y * 5 + 11) * 4) % 4;
      ctx.drawImage(set[variant], x * T, y * T, T, T);
    }
  }
  // path edges, banks and shimmer
  for (let y = y0; y < y0 + rows; y++) {
    for (let x = x0; x < x0 + cols; x++) {
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      if (pathTile(x, y)) {
        if (!pathTile(x, y - 1)) { ctx.fillStyle = 'rgba(54,49,33,.34)'; ctx.fillRect(x * T, y * T, T, 1); }
        if (!pathTile(x, y + 1)) { ctx.fillStyle = 'rgba(54,49,33,.2)'; ctx.fillRect(x * T, y * T + T - 1, T, 1); }
        if (!pathTile(x - 1, y)) { ctx.fillStyle = 'rgba(54,49,33,.22)'; ctx.fillRect(x * T, y * T, 1, T); }
        if (!pathTile(x + 1, y)) { ctx.fillStyle = 'rgba(54,49,33,.22)'; ctx.fillRect(x * T + T - 1, y * T, 1, T); }
      }
      if (isWater(x, y)) {
        if (!isWater(x, y - 1)) { ctx.fillStyle = 'rgba(160,201,182,.35)'; ctx.fillRect(x * T, y * T, T, 1); }
        if (!isWater(x, y + 1)) { ctx.fillStyle = 'rgba(32,66,62,.55)'; ctx.fillRect(x * T, y * T + T - 1, T, 1); }
        if (!isWater(x - 1, y)) { ctx.fillStyle = 'rgba(32,66,62,.45)'; ctx.fillRect(x * T, y * T, 1, T); }
        if (!isWater(x + 1, y)) { ctx.fillStyle = 'rgba(32,66,62,.45)'; ctx.fillRect(x * T + T - 1, y * T, 1, T); }
        const ph = Math.sin(clock * 2.4 + x * 0.85 + y * 0.5);
        if (ph > 0.35) {
          ctx.save();
          ctx.globalAlpha = 0.35;
          ctx.fillStyle = '#b9ddd2';
          ctx.fillRect(x * T + 2 + Math.floor(ph * 3), y * T + 3, 3, 1);
          ctx.restore();
        }
      }
    }
  }
  // ground decoration
  for (let y = y0; y < y0 + rows; y++) {
    for (let x = x0; x < x0 + cols; x++) {
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      if (pathTile(x, y) || isWater(x, y) || treeTile(x, y)) continue;
      const r = rand(x * 13 + 7, y * 17 + 3);
      if (r > 0.94 && r < 0.966) drawDeco('tuft', 0, x * T + 2, y * T + 4);
      else if (r >= 0.966 && r < 0.985) drawDeco('flower', Math.floor(r * 100) % 2, x * T + 2, y * T + 3);
      else if (r >= 0.985 && r < 0.994) drawDeco('rock', 0, x * T + 2, y * T + 4);
      else if (r >= 0.994) drawDeco('mushroom', 0, x * T + 2, y * T + 4);
    }
  }

  // y-sorted scenery and actors
  const list = [];
  for (let y = y0; y < y0 + rows; y++) {
    for (let x = x0; x < x0 + cols; x++) {
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      if (treeTile(x, y)) {
        const biome = y > 53 ? 'moss' : x > 62 ? 'autumn' : 'grass';
        const variant = Math.floor(rand(x * 7 + 5, y * 11 + 9) * 3) % 3;
        list.push({ y: y * T + 10, fn: () => drawTree(x, y, biome, variant) });
      }
    }
  }
  list.push({ y: chest.y + 5, fn: () => drawChest(chest.x, chest.y, chestOpen) });
  list.push({ y: chest2.y + 5, fn: () => drawChest(chest2.x, chest2.y, chest2Open) });
  list.push({ y: shrine.y + 4, fn: () => drawShrine(shrine.x, shrine.y) });
  list.push({ y: gate.y + 6, fn: () => drawGate(gate.x, gate.y) });
  list.push({ y: npc.y + 4, fn: () => drawNPC(npc.x, npc.y) });
  mobs.forEach(m => { if (m.alive) list.push({ y: m.y + 4, fn: () => drawMob(m) }); });
  list.push({ y: hero.y + 4, fn: drawHero });
  list.sort((a, b) => a.y - b.y);
  list.forEach(o => o.fn());

  drawParticles();
  drawFloaters();
  ctx.restore();

  drawLightRays();
  drawAmbient();
}

/* ── dungeon render ────────────────────────────────────────────────────── */
function drawDungeon() {
  $('regionTitle').textContent = '♜ CATACUMBAS DE RAÍZ';
  $('locationText').textContent = 'Catacumbas de Raíz';
  ctx.fillStyle = '#0c0e12';
  ctx.fillRect(0, 0, SW, SH);

  // walls
  for (let y = 8; y < 20; y += 8) for (let x = 4; x < SW - 4; x += 8) ctx.drawImage(TILES.wall[Math.floor(rand(x, y) * 4)], x, y, T, T);
  for (let y = 146; y < 160; y += 8) for (let x = 4; x < SW - 4; x += 8) ctx.drawImage(TILES.wall[Math.floor(rand(x + 1, y) * 4)], x, y, T, T);
  for (let y = 20; y < 148; y += 8) {
    ctx.drawImage(TILES.wall[Math.floor(rand(4, y) * 4)], 4, y, T, T);
    ctx.drawImage(TILES.wall[Math.floor(rand(5, y) * 4)], SW - 12, y, T, T);
  }
  // floor
  for (let y = 24; y < 148; y += 8) {
    for (let x = 16; x < SW - 16; x += 8) {
      ctx.drawImage(TILES.dungeon[Math.floor(rand(x * 3 + 2, y * 5 + 1) * 4)], x, y, T, T);
    }
  }
  // ambient floor moss / cracks
  for (let i = 0; i < 40; i++) {
    const x = 18 + Math.floor(rand(i + 3, i * 7 + 1) * 196);
    const y = 26 + Math.floor(rand(i * 5 + 2, i + 9) * 116);
    ctx.fillStyle = i % 3 === 0 ? 'rgba(87,108,78,.35)' : 'rgba(23,26,24,.5)';
    ctx.fillRect(x, y, 2 + (i % 3), 1);
  }

  // magic circle
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const cx = 120, cy = 58;
  const pulse = 0.18 + Math.sin(clock * 1.8) * 0.05;
  glow(cx, cy, 42, '#a4607b', pulse);
  ctx.strokeStyle = 'rgba(198,157,103,.45)';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(cx, cy, 30, 0, 7); ctx.stroke();
  ctx.strokeStyle = 'rgba(198,157,103,.25)';
  ctx.beginPath(); ctx.arc(cx, cy, 22, 0, 7); ctx.stroke();
  for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4 + clock * 0.08;
    ctx.fillStyle = 'rgba(231,197,119,.5)';
    ctx.fillRect(cx + Math.cos(a) * 26, cy + Math.sin(a) * 26, 1, 1);
  }
  ctx.restore();

  // torches and pillars
  drawDungeonTorch(26, 34); drawDungeonTorch(214, 34);
  drawDungeonTorch(26, 126); drawDungeonTorch(214, 126);
  drawPillar(58, 28); drawPillar(182, 28);

  // exit stairs
  ctx.save();
  glow(120, 143, 24, '#d9c277', 0.18);
  for (let i = 0; i < 4; i++) {
    ctx.fillStyle = i % 2 ? '#5f5741' : '#786b4d';
    ctx.fillRect(104 + i * 2, 137 + i * 2, 32 - i * 4, 2);
  }
  text('SALIDA', 108, 153, '#e3cf90', 5);
  ctx.restore();

  // actors
  const list = [];
  if (boss.alive) list.push({ y: boss.y + 12, fn: drawBoss });
  dungeonMobs.forEach(m => { if (m.alive) list.push({ y: m.y + 4, fn: () => drawMob(m) }); });
  list.push({ y: hero.y + 4, fn: drawHero });
  list.sort((a, b) => a.y - b.y);
  list.forEach(o => o.fn());

  // post-boss memorial
  if (!boss.alive) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    glow(120, 58, 20, '#9fcbb2', 0.14 + Math.sin(clock * 1.5) * 0.04);
    ctx.restore();
    text('La piedra recuerda.', 91, 50, '#9fb7a2', 5);
  }

  // fog
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i < 3; i++) {
    const gx = 70 + i * 50 + Math.sin(clock * 0.3 + i) * 12;
    const gy = 120 + Math.cos(clock * 0.25 + i) * 6;
    const g = ctx.createRadialGradient(gx, gy, 2, gx, gy, 34);
    g.addColorStop(0, 'rgba(121,148,132,.045)');
    g.addColorStop(1, 'rgba(121,148,132,0)');
    ctx.fillStyle = g;
    ctx.fillRect(gx - 34, gy - 34, 68, 68);
  }
  ctx.restore();
  drawAmbient();
  drawParticles();
  drawFloaters();
  $('interactionHint').style.display = started ? 'block' : 'none';
  $('interactionHint').textContent = boss.alive ? 'E / ESPACIO · atacar al guardián' : 'Baja hacia la salida';
}
function drawDungeonTorch(x, y) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const flick = 0.22 + Math.sin(clock * 8 + x) * 0.06;
  glow(x, y - 6, 28, '#ffbb66', flick);
  ctx.restore();
  ctx.drawImage(TORCH_SPRITE, x - 4, y - 12, 8, 12);
}
function drawPillar(x, y) {
  shadow(x + 5, y + 34, 7, 2.5, 0.35);
  ctx.fillStyle = '#24272a';
  ctx.fillRect(x, y, 10, 34);
  ctx.fillStyle = '#4b4e47';
  ctx.fillRect(x + 1, y + 2, 8, 30);
