    g.fillStyle = '#a7f0df'; g.fillRect(-5, -24, 10, 24);
    g.fillStyle = '#e4fff7'; g.fillRect(-2, -21, 4, 12);
    g.restore();
  } else {
    // Maelis, the sage
    g.save();
    g.translate(0, Math.sin(clock * 1.7) > 0.94 ? 1 : 0);
    // robe
    g.fillStyle = '#3b2e50';
    g.beginPath(); g.moveTo(18, 128); g.lineTo(30, 84); g.lineTo(98, 84); g.lineTo(110, 128); g.closePath(); g.fill();
    g.fillStyle = '#675180';
    g.beginPath(); g.moveTo(28, 128); g.lineTo(38, 88); g.lineTo(90, 88); g.lineTo(100, 128); g.closePath(); g.fill();
    g.fillStyle = '#8a72a3';
    g.fillRect(40, 92, 4, 30); g.fillRect(84, 92, 4, 30);
    g.fillStyle = '#d8bb69';
    g.fillRect(60, 92, 8, 30);
    // hood
    g.fillStyle = '#2b2238';
    g.beginPath(); g.ellipse(64, 54, 38, 42, 0, Math.PI, 0); g.fill();
    g.fillRect(26, 54, 76, 36);
    g.fillStyle = '#433255';
    g.beginPath(); g.ellipse(64, 54, 32, 36, 0, Math.PI, 0); g.fill();
    // face
    g.fillStyle = '#efc7a2';
    g.beginPath(); g.ellipse(64, 58, 18, 22, 0, 0, 7); g.fill();
    g.fillStyle = '#d7a17d';
    g.fillRect(49, 72, 30, 3);
    // hair
    g.fillStyle = '#e3dbc3';
    g.fillRect(44, 38, 40, 8);
    g.fillRect(40, 44, 6, 32);
    g.fillRect(82, 44, 6, 34);
    g.fillStyle = '#fff7df';
    g.fillRect(47, 44, 5, 16);
    g.fillRect(76, 46, 4, 14);
    // circlet
    g.fillStyle = '#d9b85e';
    g.fillRect(48, 45, 32, 2);
    g.fillStyle = '#f4dd91';
    g.fillRect(62, 43, 4, 4);
    // eyes
    const blink = (clock % 4.4) > 4.22;
    g.fillStyle = '#2b2732';
    if (blink) {
      g.fillRect(54, 60, 7, 1); g.fillRect(69, 60, 7, 1);
    } else {
      g.fillRect(55, 58, 5, 4); g.fillRect(70, 58, 5, 4);
      g.fillStyle = '#8b6f9c'; g.fillRect(56, 59, 2, 2); g.fillRect(71, 59, 2, 2);
      g.fillStyle = '#fff3cf'; g.fillRect(57, 59, 1, 1); g.fillRect(72, 59, 1, 1);
    }
    // nose + mouth
    g.fillStyle = '#d7a17d'; g.fillRect(64, 66, 2, 2);
    const talking = Math.sin(clock * 9) > 0;
    g.fillStyle = '#8b4e4a';
    g.fillRect(59, 72, 10, talking ? 3 : 1);
    if (talking) { g.fillStyle = '#b97f74'; g.fillRect(61, 73, 6, 1); }
    // staff
    g.fillStyle = '#6c4b31'; g.fillRect(104, 48, 3, 72);
    g.fillStyle = '#d4b45f'; g.fillRect(102, 44, 7, 5);
    g.fillStyle = '#e9f2c0'; g.fillRect(104, 39, 3, 6);
    g.restore();
  }

  // soft foreground vignette
  const v = g.createRadialGradient(64, 60, 26, 64, 64, 66);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(1, 'rgba(0,0,0,.45)');
  g.fillStyle = v;
  g.fillRect(0, 0, 128, 128);
}

/* ── main render / simulation ──────────────────────────────────────────── */
function draw() {
  ctx.setTransform(RS, 0, 0, RS, 0, 0);
  ctx.clearRect(0, 0, SW, SH);
  if (mode === 'world') drawWorld();
  else drawDungeon();
  drawPost();
  drawCompass();
  drawPortrait();
}
function overlayOpen() {
  return overlayNames.some(k => !$(k).classList.contains('hidden'));
}
function move(dt) {
  if (!started || overlayOpen()) { moving = false; return; }
  if (action.type === 'talk' || action.type === 'interact' || action.type === 'pray' || action.type === 'attack' || action.type === 'hurt') {
    moving = false;
    return;
  }
  let dx = (keys.ArrowRight || keys.d || keys.D ? 1 : 0) - (keys.ArrowLeft || keys.a || keys.A ? 1 : 0);
  let dy = (keys.ArrowDown || keys.s || keys.S ? 1 : 0) - (keys.ArrowUp || keys.w || keys.W ? 1 : 0);
  if (!dx && !dy) { moving = false; return; }
  if (dx && dy) { dx *= 0.707; dy *= 0.707; }
  moving = true;
  const sp = (hero.speed || 38) + (artifactEquipped && artifact ? (artifact.speed || 0) : 0);
  const speed = sp * dt;
  const nx = hero.x + dx * speed, ny = hero.y + dy * speed;
  if (!blocked(nx, hero.y)) hero.x = nx;
  if (!blocked(hero.x, ny)) hero.y = ny;
  hero.facing = dir8(dx, dy);
  walkPhase += dt * 9;
}
function frame(now) {
  const dt = Math.min(0.05, (now - last) / 1000 || 0);
  last = now;
  clock += dt;
  hero.attack = Math.max(0, hero.attack - dt);
  hero.atkCd = Math.max(0, hero.atkCd - dt);
  shake = Math.max(0, shake - dt * 18);
  flash = Math.max(0, flash - dt);
  whiteFlash = Math.max(0, whiteFlash - dt);

  if (started) {
    updateAction(dt);
    if (!overlayOpen()) {
      move(dt);
      updateEnemies(dt);
      updateBoss(dt);
    } else {
      moving = false;
    }
    if (mode === 'dungeon' && hero.y > 138 && hero.x > 100 && hero.x < 140) changeMode('world');
    updateDay(dt);
    updateParticles(dt);
    updateFloaters(dt);
    updateCamera(dt);
  } else {
    moving = false;
    updateCamera(dt);
    updateDay(dt);
  }
  draw();
  requestAnimationFrame(frame);
}

/* ── events and boot ───────────────────────────────────────────────────── */
const HINTS = {
  Guardiana: 'Escudo firme · +4 vida máxima',
