function boot() {
  buildHeroSprites();
  npcSprites = buildCharacter(npcPalette, { staff: true, robe: true });
  $('classHint').textContent = HINTS.Guardiana;
  updateUI();
  updateContinueButton();
  cam.x = clamp(hero.x - SW / 2, 0, W * T - SW);
  cam.y = clamp(hero.y - SH / 2, 0, H * T - SH);

  $('newGame').onclick = () => overlay('creatorOverlay');
  $('continueGame').onclick = () => { if (!loadGame()) overlay('creatorOverlay'); };
  $('creatorBack').onclick = () => overlay('startOverlay');
  $('createHero').onclick = resetGame;
  $('saveBtn').onclick = () => saveGame(false);
  $('inventoryBtn').onclick = openInventory;
  $('closeInventory').onclick = () => overlay(null);
  $('dungeonBack').onclick = () => overlay(null);
  $('dungeonEnter').onclick = () => changeMode('dungeon');
  $('endingContinue').onclick = () => { overlay(null); toast('El bosque sigue abierto. Explora sus secretos.'); };
  $('endingMenu').onclick = () => { overlay('startOverlay'); updateContinueButton(); };
  $('touchTalk').onclick = interact;
  $('touchAttack').onclick = () => { if (!overlayOpen()) attack(); };

  document.querySelectorAll('#classChoices .choice').forEach(b => {
    b.onclick = () => {
      document.querySelectorAll('#classChoices .choice').forEach(x => x.classList.remove('selected'));
      b.classList.add('selected');
      previewHero();
    };
  });
  document.querySelectorAll('#colorChoices .swatch').forEach(b => {
    b.onclick = () => {
      document.querySelectorAll('#colorChoices .swatch').forEach(x => x.classList.remove('selected'));
      b.classList.add('selected');
      previewHero();
    };
  });
  document.querySelectorAll('.touch-controls button').forEach(b => {
    const key = { up: 'ArrowUp', down: 'ArrowDown', left: 'ArrowLeft', right: 'ArrowRight' }[b.dataset.dir];
    b.addEventListener('pointerdown', e => { e.preventDefault(); keys[key] = true; });
    ['pointerup', 'pointercancel', 'pointerleave'].forEach(type => b.addEventListener(type, () => { keys[key] = false; }));
  });

  window.addEventListener('keydown', e => {
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) e.preventDefault();
    if (e.repeat) return;
    keys[e.key] = true;
    if (e.key === 'e' || e.key === 'E') { if (!overlayOpen()) interact(); }
    if (e.key === ' ') { if (started && !overlayOpen()) attack(); }
    if (e.key === 'i' || e.key === 'I') {
      if (!$('inventoryOverlay').classList.contains('hidden')) overlay(null);
      else if (!overlayOpen()) openInventory();
    }
    if (e.key === 'Escape') {
      if (!$('inventoryOverlay').classList.contains('hidden')) overlay(null);
      else if (!$('dialogOverlay').classList.contains('hidden')) overlay(null);
      else if (!$('dungeonOverlay').classList.contains('hidden')) overlay(null);
      else if (!$('creatorOverlay').classList.contains('hidden')) overlay('startOverlay');
    }
  });
  window.addEventListener('keyup', e => { keys[e.key] = false; });
  window.addEventListener('blur', () => { keys = {}; });

  requestAnimationFrame(frame);
}
boot();
})();

