function buildTileSet(base, kind, seed) {
  const out = [];
  const dark = shade(base, -0.12), light = shade(base, 0.12);
  for (let v = 0; v < 4; v++) {
    const s = sprite(16, 16), g = s.g;
    for (let y = 0; y < 16; y++) {
      for (let x = 0; x < 16; x++) {
        const r = rand(x * 13 + v * 71 + seed, y * 7 + v * 37 + seed);
        p(g, x, y, 1, 1, r > 0.84 ? light : r < 0.13 ? dark : base);
      }
    }
    if (kind === 'grass' || kind === 'autumn' || kind === 'moss') {
      for (let i = 0; i < 7; i++) {
        const x = Math.floor(rand(i + v * 9 + seed, seed + i) * 14) + 1;
        const y = Math.floor(rand(seed + i * 3, i + v * 7) * 12) + 2;
        p(g, x, y, 1, 2, kind === 'autumn' ? '#9a8c4c' : kind === 'moss' ? '#5f8a63' : '#6f9a5f');
        if (i % 3 === 0) p(g, x - 1, y + 1, 1, 1, kind === 'autumn' ? '#b3914a' : '#5b844f');
      }
      if (v % 2 === 0) {
        const fx = 3 + Math.floor(rand(seed, v + 1) * 9), fy = 3 + Math.floor(rand(v + 4, seed) * 9);
        const petal = kind === 'autumn' ? '#e0a65a' : kind === 'moss' ? '#b7c9e0' : '#f2e6b2';
        p(g, fx, fy, 1, 1, petal); p(g, fx + 2, fy, 1, 1, petal);
        p(g, fx + 1, fy - 1, 1, 1, petal); p(g, fx + 1, fy + 1, 1, 1, petal);
        p(g, fx + 1, fy, 1, 1, '#e6c766');
      }
    } else if (kind === 'path') {
      for (let i = 0; i < 6; i++) {
        const x = Math.floor(rand(i + seed, v + i * 5) * 13) + 1;
        const y = Math.floor(rand(v + i * 7, seed + i) * 13) + 1;
        p(g, x, y, 1 + (i % 2), 1, i % 2 ? '#b8a275' : '#7b6a4b');
      }
      p(g, 2, 12, 5, 1, '#8b7854');
      p(g, 10, 3, 3, 1, '#aa9469');
    } else if (kind === 'water') {
      for (let i = 0; i < 4; i++) {
        const y = 3 + i * 3 + (v % 2);
        p(g, 2 + ((i + v) % 3), y, 6 + (i % 3), 1, i % 2 ? '#4f8588' : '#3b6b70');
        p(g, 8 - (i % 2), y + 1, 3, 1, '#6da3a2');
      }
      p(g, 2, 2, 2, 1, '#8fc1bb');
    } else if (kind === 'dungeon') {
      p(g, 0, 0, 16, 1, '#252823');
      p(g, 0, 15, 16, 1, '#252823');
      p(g, 0, 0, 1, 16, '#2b2e29');
      p(g, 15, 0, 1, 16, '#2b2e29');
      for (let i = 0; i < 5; i++) {
        const x = Math.floor(rand(i + v * 11, seed) * 12) + 2;
        const y = Math.floor(rand(seed + i, v + 3) * 12) + 2;
        p(g, x, y, 2, 1, '#4b4d44');
      }
      if (v === 0) p(g, 4, 6, 5, 1, '#2c2f2a');
      if (v === 2) p(g, 9, 10, 4, 1, '#2c2f2a');
    } else if (kind === 'wall') {
      for (let y = 0; y < 16; y += 5) {
        p(g, 0, y, 16, 1, '#17191d');
        const off = (y / 5) % 2 ? 4 : 0;
        for (let x = -off; x < 16; x += 8) p(g, x, y + 1, 1, 4, '#17191d');
      }
      for (let i = 0; i < 4; i++) {
        const x = Math.floor(rand(i + v, seed) * 14) + 1;
        const y = Math.floor(rand(seed + 3, i + v) * 14) + 1;
        p(g, x, y, 1, 1, '#41464a');
      }
    }
    out.push(s.c);
  }
  return out;
}

