  sheet: () => {
    const dirs = ['S', 'SE', 'E', 'NE', 'N', 'NW', 'W', 'SW'];
    const states = ['idle', 'walk', 'talk', 'interact', 'attack', 'hurt'];
    const cw = 34, ch = 50;
    const c = document.createElement('canvas');
    c.width = 4 * cw * 2; c.height = dirs.length * ch;
    const g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    g.fillStyle = '#243d2c'; g.fillRect(0, 0, c.width, c.height);
    dirs.forEach((d, row) => {
      states.forEach((st, si) => {
        const frames = heroSprites[d][st];
        frames.slice(0, 2).forEach((img, fi) => {
          const x = (si * 2 + fi) * cw, y = row * ch;
          g.drawImage(img, x, y, 32, 48);
        });
      });
    });
    return c.toDataURL();
  }
};

